// AuthServiceClient is a client for the inaba.v1.AuthService service.
type AuthServiceClient interface {
	// Needs no sign-in.
	GetConfig(context.Context, *v1.GetConfigRequest) (*v1.GetConfigResponse, error)
	// Creates the first account on a server that has none, and signs it in. The token
	// comes from the onboarding link the server prints when it starts without accounts.
	// Needs no sign-in.
	Onboard(context.Context, *v1.OnboardRequest) (*v1.User, error)
	// Sets the session cookie.
	Login(context.Context, *v1.LoginRequest) (*v1.User, error)
	Logout(context.Context, *v1.LogoutRequest) (*v1.LogoutResponse, error)
	WhoAmI(context.Context, *v1.WhoAmIRequest) (*v1.User, error)
	// Creates an API token for scripts. The secret is returned only here.
	CreateToken(context.Context, *v1.CreateTokenRequest) (*v1.CreateTokenResponse, error)
	ListTokens(context.Context, *v1.ListTokensRequest) (*v1.ListTokensResponse, error)
	RevokeToken(context.Context, *v1.RevokeTokenRequest) (*v1.RevokeTokenResponse, error)
	// Changes the signed-in account's own profile; a field left out stays as it is.
	UpdateProfile(context.Context, *v1.UpdateProfileRequest) (*v1.User, error)
	ChangePassword(context.Context, *v1.ChangePasswordRequest) (*v1.ChangePasswordResponse, error)
	// Two-step sign-in with an authenticator app: begin makes a secret to scan, enable
	// turns it on once a code from the app checks out, disable needs a code too.
	BeginTotp(context.Context, *v1.BeginTotpRequest) (*v1.BeginTotpResponse, error)
	EnableTotp(context.Context, *v1.EnableTotpRequest) (*v1.User, error)
	DisableTotp(context.Context, *v1.DisableTotpRequest) (*v1.User, error)
	// The account's sign-ins in browsers, to end any of them.
	ListSessions(context.Context, *v1.ListSessionsRequest) (*v1.ListSessionsResponse, error)
	RevokeSession(context.Context, *v1.RevokeSessionRequest) (*v1.RevokeSessionResponse, error)
	// Passkeys sign in without a password. Registering one is begin then finish.
	ListPasskeys(context.Context, *v1.ListPasskeysRequest) (*v1.ListPasskeysResponse, error)
	BeginPasskeyRegistration(context.Context, *v1.BeginPasskeyRequest) (*v1.BeginPasskeyResponse, error)
	FinishPasskeyRegistration(context.Context, *v1.FinishPasskeyRegistrationRequest) (*v1.Passkey, error)
	DeletePasskey(context.Context, *v1.DeletePasskeyRequest) (*v1.DeletePasskeyResponse, error)
	// Signing in with a passkey, without an account yet: the passkey says whose it is.
	BeginPasskeyLogin(context.Context, *v1.BeginPasskeyRequest) (*v1.BeginPasskeyResponse, error)
	FinishPasskeyLogin(context.Context, *v1.FinishPasskeyLoginRequest) (*v1.User, error)
}

