// HostServiceClient is a client for the inaba.v1.HostService service.
type HostServiceClient interface {
	// Registers a host. The secret is returned only here; start the host with it.
	CreateHost(context.Context, *v1.CreateHostRequest) (*v1.CreateHostResponse, error)
	ListHosts(context.Context, *v1.ListHostsRequest) (*v1.ListHostsResponse, error)
	// Makes a link that lets whoever signs in and opens it into a host with a role, for a
	// week. The host's owner's or managers' to make, or an administrator's. The secret is
	// returned only here.
	CreateHostInvite(context.Context, *v1.CreateHostInviteRequest) (*v1.CreateHostInviteResponse, error)
	// Ends every invite link of a host; those who already joined stay.
	RevokeHostInvites(context.Context, *v1.RevokeHostInvitesRequest) (*v1.RevokeHostInvitesResponse, error)
	// The invite links of a host that still work, without their secrets. The host's
	// owner's or managers' to see, or an administrator's.
	ListHostInvites(context.Context, *v1.ListHostInvitesRequest) (*v1.ListHostInvitesResponse, error)
	// Ends one invite link of a host.
	RevokeHostInvite(context.Context, *v1.RevokeHostInviteRequest) (*v1.RevokeHostInviteResponse, error)
	// What an invite link leads to, before joining.
	GetHostInvite(context.Context, *v1.GetHostInviteRequest) (*v1.HostInvite, error)
	// Joins the host an invite link is for, with the role it grants.
	AcceptHostInvite(context.Context, *v1.AcceptHostInviteRequest) (*v1.Host, error)
	// Who was let into a personal host. Its owner's, or an administrator's, to see.
	ListHostMembers(context.Context, *v1.ListHostMembersRequest) (*v1.ListHostMembersResponse, error)
	RemoveHostMember(context.Context, *v1.RemoveHostMemberRequest) (*v1.RemoveHostMemberResponse, error)
	// Lets an account into a host with a role, changes its role, or takes it out. The
	// host's owner's or managers' to do, or an administrator's.
	SetHostMember(context.Context, *v1.SetHostMemberRequest) (*v1.SetHostMemberResponse, error)
	DeleteHost(context.Context, *v1.DeleteHostRequest) (*v1.DeleteHostResponse, error)
	// Changes how a host is named and shown. Its look is for whoever may change its settings;
	// its name, like removing it, is its owner's, an administrator's, or for a shared host
	// theirs who may add shared hosts.
	UpdateHost(context.Context, *v1.UpdateHostRequest) (*v1.Host, error)
	// Signing a machine in as a host, the way a device signs in to a TV app: `inaba login`
	// starts it without an account and shows a code; a signed-in user approves the
	// code in the browser; the host then gets a refresh token it keeps.
	StartHostLogin(context.Context, *v1.StartHostLoginRequest) (*v1.StartHostLoginResponse, error)
	// Asked by the host every interval until the login is approved, denied, or expires.
	PollHostLogin(context.Context, *v1.PollHostLoginRequest) (*v1.PollHostLoginResponse, error)
	// What a user is about to approve.
	GetHostLogin(context.Context, *v1.GetHostLoginRequest) (*v1.HostLogin, error)
	// Registers the machine as a host of the caller's, or with shared, of every account's.
	ApproveHostLogin(context.Context, *v1.ApproveHostLoginRequest) (*v1.Host, error)
	DenyHostLogin(context.Context, *v1.DenyHostLoginRequest) (*v1.DenyHostLoginResponse, error)
	// Trades a host's refresh token for a short-lived access token to connect with.
	RefreshHostToken(context.Context, *v1.RefreshHostTokenRequest) (*v1.RefreshHostTokenResponse, error)
}

