// AdminServiceClient is a client for the inaba.v1.AdminService service.
type AdminServiceClient interface {
	ListUsers(context.Context, *v1.ListUsersRequest) (*v1.ListUsersResponse, error)
	// Creates an account that signs in with a password. It starts with no permissions.
	CreateUser(context.Context, *v1.CreateUserRequest) (*v1.User, error)
	// Changes a password account's password and signs it out everywhere.
	SetPassword(context.Context, *v1.SetPasswordRequest) (*v1.SetPasswordResponse, error)
	// Replaces what an account is allowed to do. The last administrator stays one.
	SetAccess(context.Context, *v1.SetAccessRequest) (*v1.User, error)
	// Removes an account, its sign-ins and its API tokens.
	DeleteUser(context.Context, *v1.DeleteUserRequest) (*v1.DeleteUserResponse, error)
	// Lists every account's API tokens.
	ListUserTokens(context.Context, *v1.ListUserTokensRequest) (*v1.ListUserTokensResponse, error)
	CreateUserToken(context.Context, *v1.CreateUserTokenRequest) (*v1.CreateTokenResponse, error)
	RevokeUserToken(context.Context, *v1.RevokeTokenRequest) (*v1.RevokeTokenResponse, error)
	// An account in full: who it is, how it signs in, and its place on every host.
	GetUserDetail(context.Context, *v1.GetUserDetailRequest) (*v1.UserDetail, error)
	// Signs an account out everywhere.
	EndUserSessions(context.Context, *v1.EndUserSessionsRequest) (*v1.EndUserSessionsResponse, error)
	// Turns off an account's two-step sign-in, as when its authenticator is lost.
	DisableUserTotp(context.Context, *v1.DisableUserTotpRequest) (*v1.User, error)
	// What the server keeps that may be cleared: its database, and sign-ins and tokens
	// that have expired. Each host has its own, at /v1/hosts/{host_id}/housekeeping.
	GetServerHousekeeping(context.Context, *v1.GetServerHousekeepingRequest) (*v1.ServerHousekeeping, error)
	CleanUpServer(context.Context, *v1.CleanUpServerRequest) (*v1.ServerHousekeeping, error)
}

