// PresenceServiceClient is a client for the inaba.v1.PresenceService service.
type PresenceServiceClient interface {
	// Says where this browser is and returns everyone else seen on that host in the last
	// half minute. Call it every few seconds while the page is open.
	Heartbeat(context.Context, *v1.HeartbeatRequest) (*v1.HeartbeatResponse, error)
	// Records that the caller has read a thread up to an event, for unread markers: the
	// thread is unread while its last_seq is above the seq kept here. The kept seq only
	// moves forward, so two tabs reporting out of order do not mark it unread again.
	MarkThreadSeen(context.Context, *v1.MarkThreadSeenRequest) (*v1.ThreadSeen, error)
	// What the caller has read of each thread on a host. A thread missing here was never opened.
	ListThreadSeen(context.Context, *v1.ListThreadSeenRequest) (*v1.ListThreadSeenResponse, error)
}

